import{_ as a}from"./chunks/rayrai_usd_nvidia_robots.8TxT2oWN.js";import{_ as s,o as t,c as o,a5 as i}from"./chunks/framework.DrDMl0tG.js";const b=JSON.parse('{"title":"Server Example: NVIDIA USD Robots","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/nvidia_usd_robots.md","filePath":"sections/examples/server/nvidia_usd_robots.md"}'),r={name:"sections/examples/server/nvidia_usd_robots.md"};function d(l,e,n,c,h,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="server-example-nvidia-usd-robots" tabindex="-1">Server Example: NVIDIA USD Robots <a class="header-anchor" href="#server-example-nvidia-usd-robots" aria-label="Permalink to &quot;Server Example: NVIDIA USD Robots&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Loads three bundled Isaac Sim robot USD files with <code>World::addUsdArticulatedSystem</code> and publishes them together through <code>RaisimServer</code>. The example is intentionally limited to assets that were smoke-tested as RaiSim articulated systems with supported collision bodies. See <a href="./../../OpenUSD.html">OpenUSD Loading</a>.</p><p><img src="'+a+'" alt="Collision bodies from three Isaac Sim USD robot assets imported into RaiSim"></p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>nvidia_usd_robots</code> (C++20). RaiSim loads USD through its bundled OpenUSD runtime on every supported platform, so no extra build switch is needed.</p><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><p>The bundled assets are:</p><ul><li><code>create3</code>: <code>rsc/isaac/Robots/iRobot/Create3/create_3.usd</code> (BSD-3)</li><li><code>jetbot</code>: <code>rsc/isaac/Robots/NVIDIA/Robomaker/aws_robomaker_jetbot.usd</code> (MIT)</li><li><code>ant</code>: <code>rsc/isaac/Robots/IsaacSim/Ant/ant.usd</code> (MIT)</li></ul><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/nvidia_usd_robots</span></span></code></pre></div><p>On Windows, run <code>nvidia_usd_robots.exe</code> instead. This example uses RaisimServer. Start <code>rayrai_tcp_viewer</code> and connect to port 8080.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads each USD file with <code>World::addUsdArticulatedSystem</code> and simulates at 500 Hz.</li><li>Throws an error if a USD file does not import as an articulated system or if no supported collision bodies are imported.</li><li>Places the imported floating bases above a checkerboard ground and applies a shared <code>nvidia_usd_robot</code> collision material.</li></ul>',15)])])}const _=s(r,[["render",d]]);export{b as __pageData,_ as default};
